tatement": "SAK:n historiakuvauksen mukaan keskusjärjestö osallistui vuodesta 1968 muiden työntekijä- ja työnantajakeskusjärjestöjen kanssa tulopoliittisiin kokonaisratkaisuihin.", "source_ids": ["tupo"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["työmarkkinoiden keskusjärjestöt"], "affected_groups": ["järjestöjen jäsenet", "järjestäytymättömät työntekijät"], "mechanism_hypothesis": "Keskitetty valmistelu saattoi vahvistaa keskusjärjestöjen asemaa ratkaisujen määrittelijöinä.", "case_limitations": "Osapuolinäkökulma säilytetään. Sopiminen ei siirtänyt eduskunnan budjetti- tai lainsäädäntövaltaa järjestöille; vaikutuksen jakautumista ryhmiin ei tässä mitata.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1946_1975_20261026:school1972", "primary_item_id": "education_needs_1946_1975_20261022:reform1972", "reuse_existing_item": true, "title": "Peruskoulun porrastettu toimeenpano ja yhteinen koulutusreitti", "year_start": 1972, "year_end": 1975, "theme_ids": [4, 8, 19, 26], "dimension_codes": ["decision_authority", "resource_control", "access_representation"], "source_ids": ["school"], "observations": [{"observation_id": "institutional_power_1946_1975_20261026:school1972:1", "statement": "Peruskouluun siirryttiin alueittain 1972–1977, ensin Pohjois-Suomessa ja viimeksi Helsingissä. Kansakoulu, kansalaiskoulu ja keskikoulu yhdistettiin yhteiseksi oppivelvollisuuskouluksi.", "source_ids": ["school"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["kouluhallinto", "kunnat", "oppilaitokset"], "affected_groups": ["oppilaat", "perheet"], "mechanism_hypothesis": "Yhteinen koulutusreitti saattoi muuttaa aiemman valikoinnin ja koulutukseen pääsyn ehtoja.", "case_limitations": "Kortin loppuvuosi 1975 on keruurajaus, ei uudistuksen valmistumisvuosi. Vaikutusta toimeentuloon ei päätellä tästä toimeenpanohavainnosta.", "formal_authority_status": "phased_implementation_scope_clipped", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1946_1975_20261026:jsn1968", "primary_item_id": "knowledge_power_1946_1975_20261024:jsn1968", "reuse_existing_item": true, "title": "Journalistinen itsesääntely erillisenä valvontamuotona", "year_start": 1968, "year_end": 1968, "theme_ids": [19, 28, 29], "dimension_codes": ["oversight_accountability", "agenda_preparation"], "source_ids": ["jsn"], "observations": [{"observation_id": "institutional_power_1946_1975_20261026:jsn1968:1", "statement": "JSN:n perussopimus allekirjoitettiin 10.12.1968 toimittaja- ja kustantajatahojen muodostamaa itsesääntelyä varten.", "source_ids": ["jsn"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["toimittajien ja kustantajien järjestöt", "JSN"], "affected_groups": ["yleisöt", "journalismin kohteet"], "mechanism_hypothesis": "Ammattietiikan valvonta muodostui lainsäädännöstä erilliseksi vastuun kanavaksi.", "case_limitations": "JSN ei ole tuomioistuin tai pakkovallan käyttäjä. Nykyisiä jäsenyyksiä, ohjeita tai rahoitussuhteita ei oleteta samaksi vuonna 1968.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1946_1975_20261026:health1972", "primary_item_id": "kansanterveyslaki-1972", "reuse_existing_item": true, "title": "Kunnan palvelutehtävä ja valtakunnallinen terveyssuunnittelu", "year_start": 1972, "year_end": 1972, "theme_ids": [7, 8, 17, 20], "dimension_codes": ["decision_authority", "resource_control"], "source_ids": ["health"], "observations": [{"observation_id": "institutional_power_1946_1975_20261026:health1972:1", "statement": "Aikalaisläheisen virallisen tilastojulkaisun mukaan kansanterveyslaki 66/1972 määräsi kunnille terveydenhuoltotehtäviä. Valtioneuvoston vahvistama valtakunnallinen suunnitelma määritteli tavoitteita ja toimeenpanovelvoitteita.", "source_ids": ["health"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["kunnat", "valtioneuvosto", "terveyshallinto"], "affected_groups": ["palvelujen käyttäjät", "kuntalaiset"], "mechanism_hypothesis": "Paikallisen toimeenpanon ja valtakunnallisen suunnittelun yhdistelmä jakoi palveluohjausta eri hallintotasoille.", "case_limitations": "Vuonna 1979 julkaistun tilaston takautuva kuvaus, ei vuoden 1972 alkuperäissäädöksen koko tarkistus. Ei oletusta tavoitteiden täydellisestä tai yhdenaikaisesta toteutumisesta.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1946_1975_20261026:exception1973", "primary_item_id": "cleavages_1946_1975_20261023:exception1973", "reuse_existing_item": true, "title": "Presidentin toimikauden jatkaminen ilman tavanomaista vaalia", "year_start": 1973, "year_end": 1973, "theme_ids": [8, 19, 28, 32], "dimension_codes": ["decision_authority", "access_representation"], "source_ids": ["elections"], "observations": [{"observation_id": "institutional_power_1946_1975_20261026:exception1973:1", "statement": "Vuonna 1973 säädettiin poikkeuslaki, jolla Kekkosen toimikautta jatkettiin neljällä vuodella.", "source_ids": ["elections"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["eduskunta", "presidentti"], "affected_groups": ["äänestäjät", "edustajat"], "mechanism_hypothesis": "Poikkeusmenettely korvasi yhden normaalin valintatilanteen parlamentaarisella ratkaisulla.", "case_limitations": "Tämä ei yksin osoita laajempien ulko- tai talouspoliittisten ratkaisujen syitä. Valmistelun vaihtoehdot ja painostusväitteet tarvitsevat erillisen näytön.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1946_1975_20261026:dissolutions", "primary_item_id": "institutional_power_1946_1975_20261026:dissolutions", "reuse_existing_item": false, "title": "Presidentin hajotusvallan dokumentoidut käyttökerrat", "year_start": 1953, "year_end": 1975, "theme_ids": [8, 19, 28, 32], "dimension_codes": ["decision_authority"], "source_ids": ["dissolutions"], "observations": [{"observation_id": "institutional_power_1946_1975_20261026:dissolutions:1", "statement": "Presidentin kanslian historiallinen luettelo ajoittaa ennenaikaisten eduskuntavaalien määräämiset 1953 Paasikivelle sekä 1961,1971 ja 1975 Kekkoselle.", "source_ids": ["dissolutions"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["presidentti", "eduskunta"], "affected_groups": ["äänestäjät", "edustajat"], "mechanism_hypothesis": "Hajotusvalta antoi presidentille välineen muuttaa parlamentaarisen päätöksenteon ajoitusta.", "case_limitations": "Vuodet 1953–1975 eivät kuvaa jatkuvaa hajotustilaa. Jokaisen kerran perusteet ja vaikutus arvioitava erikseen; nykyistä pääministerialoitteen vaatimusta ei sovelleta takautuvasti.", "formal_authority_status": "documented_exercise_inventory", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": [], "documented_event_years": [1953, 1961, 1971, 1975]}], "limitations": ["Muodollinen toimivalta, toimeenpanorakenne ja tosiasiallinen vaikutusvalta erotetaan. Ei uusia numeerisia vaikutusarvioita.", "Pääosa lähteistä on viranomaisten tai instituutioiden historiakoosteita. SAK:n historiakuvaus säilyttää osapuolinäkökulman.", "Finlexin1951 asiakirjalain ja1979 terveydenhuoltotilaston otteiden tarkistus on koko tekstin tarkistusta rajatumpi.", "Myöhempiä hallintoedustuksia, perustuslakimuutoksia tai ohjausjärjestelmiä ei siirretä takautuvasti.", "Toimivalta ei tarkoita käytön vaikutuksen suuruutta tai tavoitteen toteutumista."], "open_tasks": ["Presidentin hallituksenmuodostus- ja nimitysvallan tapauskohtaiset käytännöt ja eduskunnan luottamuksen merkitys.", "Puoluerahoituksen ja poliittisten nimitysten alkuperäiset säännöt, päätökset ja toteumat.", "Pankkien, suuryritysten, valtionyhtiöiden sekä kirkon omistus- ja resurssivallan kytkennät.", "Työmarkkina- ja eläkehallinnon alkuperäiset kokoonpanot, pöytäkirjat ja ryhmien tosiasiallinen edustus.", "Kunnallisen palvelusuunnittelun rahoituspäätökset, valvonta ja alueelliset toimeenpanoerot.", "Julkisuuslain ja hallintomuutoksenhaun käytännön saavutettavuus sekä toteutuneet tiedonsaantikiistat."]}$payload$::jsonb;
 e jsonb; urls text[]; d jsonb; h text; old_hash text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext(p->>'batch_id'));
 h := md5(p::text);
 SELECT data->>'payload_md5' INTO old_hash FROM public.dataset_meta WHERE id=p->>'batch_id';
 IF old_hash IS NOT NULL THEN
  IF old_hash<>h THEN RAISE EXCEPTION 'Batch payload changed; create a new version'; END IF;
  RETURN;
 END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(p->'entries') LOOP
  IF (e->>'year_start')::int<1946 OR (e->>'year_end')::int>1975 THEN RAISE EXCEPTION 'Year outside collection'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'dimension_codes') x WHERE NOT (p->'taxonomy' ? x)) THEN RAISE EXCEPTION 'Unknown dimension'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'source_ids') x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sources') s WHERE s->>'source_id'=x)) THEN RAISE EXCEPTION 'Unknown source'; END IF;
  SELECT array_agg(s->>'url' ORDER BY s->>'source_id') INTO urls FROM jsonb_array_elements(p->'sources') s WHERE e->'source_ids' ? (s->>'source_id');
  IF (e->>'reuse_existing_item')::boolean THEN
   IF NOT EXISTS(SELECT 1 FROM public.items WHERE id=e->>'primary_item_id') THEN RAISE EXCEPTION 'Missing existing item %',e->>'primary_item_id'; END IF;
   UPDATE public.items SET sources=ARRAY(SELECT DISTINCT u FROM unnest(sources||urls) u ORDER BY u),updated_at=now() WHERE id=e->>'primary_item_id' AND NOT sources @> urls;
  ELSE
   INSERT INTO public.items(id,title,year_start,year_end,type,domains,phase,problem,mechanism,effects,long_effect,current_relevance,importance,confidence,sources,subtype,evidence_confidence,interpretation_confidence)
   VALUES(e->>'primary_item_id',e->>'title',(e->>'year_start')::int,(e->>'year_end')::int,'tapahtuma',ARRAY['institutionaalinen valta','julkinen valta','oikeusvaltio'],'1946–1975',
    (SELECT string_agg(o->>'statement',' ' ORDER BY n) FROM jsonb_array_elements(e->'observations') WITH ORDINALITY x(o,n)),
    'Tulkintahypoteesi: '||(e->>'mechanism_hypothesis'),ARRAY['Lähteistetty institutionaalinen järjestely tai toimenpide; vaikutuksen suuruutta ei ole tunnistettu.'],e->>'case_limitations','Muodollisen toimivallan, edustuksen ja tosiasiallisen vaikutusvallan erottaminen.',3,'kohtalainen',urls,'institutional_power_history','kohtalainen','kehittyvä');
  END IF;
  d := e || jsonb_build_object('batch_id',p->>'batch_id','taxonomy_id',p->>'taxonomy_id','case_type','historical_institutional_power','sources',to_jsonb(urls),'item_ids',jsonb_build_array(e->>'primary_item_id')||(e->'related_item_ids'),'limitations',(p->'limitations')||jsonb_build_array(e->>'case_limitations'),'measurement_status','qualitative_documented_case','causal_confirmation',false,'numeric_effect',null,'mechanism_link_status','hypothesis_context','population_prevalence_measured',false);
  IF EXISTS(SELECT 1 FROM public.atlas_mechanism_cases WHERE data->>'case_key'=e->>'case_key') THEN RAISE EXCEPTION 'Case already exists outside manifest'; END IF;
  INSERT INTO public.atlas_mechanism_cases(title,year_start,year_end,kind,status,published,primary_item_id,data)
   VALUES(e->>'title',(e->>'year_start')::int,(e->>'year_end')::int,'history','hypothesis',true,e->>'primary_item_id',d);
 END LOOP;
 INSERT INTO public.dataset_meta(id,data) VALUES(p->>'batch_id',p||jsonb_build_object('payload_md5',h,'imported_at',now()));
END $import$;
COMMIT;
SELECT count(*) AS cases,count(DISTINCT primary_item_id) AS linked_items,sum(jsonb_array_length(data->'observations')) AS observations,count(*) FILTER(WHERE (data->>'reuse_existing_item')::boolean) AS reused_items,count(*) FILTER(WHERE NOT (data->>'reuse_existing_item')::boolean) AS new_items FROM public.atlas_mechanism_cases WHERE data->>'batch_id'='institutional_power_1946_1975_20261026';
